// --- KONFIGURASI ---
const CSV_URL = "https://docs.google.com/spreadsheets/d/e/2PACX-1vQ_0-HrBEJTG1vfHycGRu6oP9h4UaAgq7j70gskW9SriVSphZQB5DoXAiSSPrqNPEg-VCRiefvNDjLV/pub?gid=0&single=true&output=csv";
const cacheKey = "skenpat_jadwal_v1";

// --- STATE MANAGEMENT ---
let allData = [];

// --- DOM ELEMENTS ---
const loader = document.getElementById('loader');
const homeView = document.getElementById('homeView');
const scheduleView = document.getElementById('scheduleView');
const pageTitle = document.getElementById('pageTitle');
const pageSubtitle = document.getElementById('pageSubtitle');
const mobileNav = document.getElementById('mobileNav');

// --- HELPERS ---

// 1. Deteksi Jurusan dari nama kelas (contoh: x_rpl_1 -> 'rpl')
function getMajorCode(kelasName) {
    const parts = kelasName.toLowerCase().split('_');
    // Asumsi format: x_jurusan_no (contoh: x_rpl_1)
    // Jika panjang array cukup, ambil bagian tengahnya
    if (parts.length >= 2) {
        return parts[1]; // 'rpl', 'dpb', 'ulw' dan lain lain cuy (dkk)
    }
    return 'umum';
}

function getMajorDisplay(majorCode) {
    const map = {
        'rpl': 'Rekayasa Perangkat Lunak',
        'dpb': 'Desain & Produksi Busana',
        'ulw': 'Usaha Layanan Wisata',
        'seni': 'Seni Musik',
        'htl': 'Akomodasi Perhotelan',
        'boga': 'Kuliner',
        'kct': 'Tata Kecantikan Kulit & Rambut'
    };
    return map[majorCode] || majorCode.toUpperCase();
}

function getIconForMajor(majorCode) {
    if (majorCode.includes('rpl')) return 'fa-laptop-code';
    if (majorCode.includes('dpb') || majorCode.includes('busana')) return 'fa-mitten';
    if (majorCode.includes('ulw') || majorCode.includes('hotel')) return 'fa-person-walking-luggage';
    if (majorCode.includes('seni')) return 'fa-palette';
    if (majorCode.includes('htl')) return 'fa-hotel';
    if (majorCode.includes('boga') || majorCode.includes('kuliner')) return 'fa-utensils';
    if (majorCode.includes('kct')) return 'fa-hand-sparkles';
    return 'fa-book-open';
}

function getColorForIndex(index) {
    const colors = ['#FF9F43', '#FF6B6B', '#48DBFB', '#5F27CD', '#1DD1A1', '#FECA57'];
    return colors[index % colors.length];
}

// --- INIT ---
document.addEventListener('DOMContentLoaded', async () => {
    await fetchData();
    handleRouting();
});

// --- FITUR BARU: FORCE REFRESH ---
function forceRefresh() {
    const konfirmasi = confirm("Yakin ingin reset cache? Website akan memuat ulang data dari server (butuh internet).");
    if (konfirmasi) {
        localStorage.removeItem(cacheKey);
        location.reload();
    }
}

// --- DATA FETCHING (OFFLINE FIRST LOGIC) ---
async function fetchData() {
    // 1. Cek Cache dulu (Offline Priority)
    const cached = localStorage.getItem(cacheKey);
    if (cached) {
        try {
            allData = JSON.parse(cached);
            console.log("✅ Menggunakan data cache (Mode Offline/Speed).");
            // Jika ada cache, langsung sembunyikan loader biar user nggak nunggu lama
            loader.classList.add('hidden');
            // Jangan return di sini, kita tetap coba update di background
        } catch (e) {
            console.error("Cache rusak, akan di-fetch ulang.");
        }
    }

    // 2. Coba Fetch Online (untuk update data baru)
    try {
        const response = await fetch(CSV_URL);
        if (!response.ok) throw new Error("yahh, gagal koneksi server nich :(");

        const csvText = await response.text();
        const parsed = Papa.parse(csvText, { header: true });
        const newData = parsed.data.filter(row => row.kelas && row.hari && row.mapel);

        if (newData.length > 0) {
            localStorage.setItem(cacheKey, JSON.stringify(newData));
            allData = newData; // Update variable global
            console.log("🌐 Data berhasil diupdate dari server.");

            // Jika tampilan sudah muncul (dari cache), kita refresh UI silently
            // agar data yang tampilkan adalah yang terbaru
            if (loader.classList.contains('hidden')) {
                const params = new URLSearchParams(window.location.search);
                if (params.get('kelas')) renderScheduleView(params.get('kelas'));
                else renderHomeView();
            }
        }
    } catch (error) {
        console.error("Gagal fetch online:", error);
        // Jika gagal fetch DAN allData kosong (belum pernah buka sama sekali)
        if (allData.length === 0) {
            alert("⚠️ Gagal memuat data. Coba periksa koneksi internetmu. okeii?");
            loader.classList.add('hidden');
        }
        // Jika gagal fetch TAPI allData ada (dari cache), biarkan saja (Offline mode jalan)
    }
}

// --- ROUTING ---
function handleRouting() {
    const params = new URLSearchParams(window.location.search);
    const kelasParam = params.get('kelas');

    if (kelasParam) {
        renderScheduleView(kelasParam);
    } else {
        renderHomeView();
    }
}

// --- RENDER HOME VIEW (GROUPED BY MAJOR) ---
function renderHomeView() {
    homeView.classList.remove('hidden');
    scheduleView.classList.remove('active');
    mobileNav.classList.add('hidden');

    pageTitle.textContent = "Mapel Kelas X 📚";
    pageSubtitle.textContent = "Pilih jurusanmu, lalu pilih kelas! okeii?";

    // 1. Group Kelas berdasarkan Major Code
    const majorGroups = {};
    allData.forEach(d => {
        const major = getMajorCode(d.kelas);
        if (!majorGroups[major]) majorGroups[major] = new Set();
        majorGroups[major].add(d.kelas);
    });

    // 2. Render Grid
    const grid = document.getElementById('kelasGrid');
    grid.innerHTML = '';

    // Urutkan jurusan (alphabetical)
    const sortedMajors = Object.keys(majorGroups).sort();

    if (sortedMajors.length === 0) {
        grid.innerHTML = `<div class="jurusan-card"><p>Data tidak tersedia. Tekan tombol 'Reset Data' jika terjadi error.</p></div>`;
        return;
    }

    sortedMajors.forEach((major, index) => {
        // Ambil semua kelas di jurusan ini dan Sort Natural (1, 2, 10 bukan 1, 10, 2)
        const kelasList = Array.from(majorGroups[major]).sort((a, b) => {
            return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
        });

        const color = getColorForIndex(index);
        const icon = getIconForMajor(major);
        const displayName = getMajorDisplay(major);

        const card = document.createElement('div');
        card.className = 'jurusan-card';

        card.innerHTML = `
          <div class="jurusan-header" style="background-color: ${color}">
            <h2>
              <i class="fa-solid ${icon}"></i>
              ${displayName}
            </h2>
          </div>
          <div class="jurusan-content">
            <p style="margin-bottom: 0.5rem; font-size: 0.9rem; color: #777;">Pilih Kelas:</p>
            <div class="kelas-select-wrapper">
              <select class="kelas-select" onchange="window.location.href='?kelas='+this.value">
                <option value="" disabled selected>-- Pilih --</option>
                ${kelasList.map(k => `<option value="${k}">${k.toUpperCase().replace(/_/g, ' ')}</option>`).join('')}
              </select>
            </div>
          </div>
        `;
        grid.appendChild(card);
    });
}

// --- RENDER SCHEDULE VIEW ---
function renderScheduleView(kelas) {
    homeView.classList.add('hidden');
    scheduleView.classList.add('active');

    pageTitle.textContent = `Jadwal ${kelas.replace(/_/g, ' ').toUpperCase()}`;
    pageSubtitle.textContent = "Semester 2 - 2025/2026";

    // Populate Dropdown Switcher
    const switcher = document.getElementById('kelasSwitcher');
    // Ambil semua kelas unik (global) agar bisa pindah ke jurusan lain cepat
    const allKelas = [...new Set(allData.map(d => d.kelas))].sort((a, b) => {
        return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
    });

    switcher.innerHTML = `<option value="">Pindah Kelas Cepat...</option>`;
    allKelas.forEach(k => {
        const opt = document.createElement('option');
        opt.value = k;
        opt.textContent = k.toUpperCase();
        if (k === kelas) opt.selected = true;
        switcher.appendChild(opt);
    });

    // Filter Data
    const kelasData = allData.filter(d => d.kelas === kelas);

    // Group by Hari
    const groupedByDay = kelasData.reduce((acc, curr) => {
        if (!acc[curr.hari]) acc[curr.hari] = [];
        acc[curr.hari].push(curr);
        return acc;
    }, {});

    const dayOrder = ["Senin", "Selasa", "Rabu", "Kamis", "Jumat"];
    const container = document.getElementById('scheduleContent');
    container.innerHTML = '';

    renderMobileNav(dayOrder);

    dayOrder.forEach(day => {
        if (groupedByDay[day]) {
            const dayData = groupedByDay[day].sort((a, b) => {
                return parseInt(a.jam) - parseInt(b.jam);
            });

            const dayCard = document.createElement('div');
            dayCard.className = 'day-card';
            dayCard.id = `section-${day.toLowerCase()}`;

            let listHTML = '';
            dayData.forEach(item => {
                if (item.mapel.toLowerCase().includes('istirahat')) {
                    listHTML += `
                <li class="subject-item break">
                   <div style="display:flex; flex-direction:column; align-items:center;">
                    <span>${item.mapel.toUpperCase()}</span>
                    <span style="font-size: 0.8rem; font-weight: normal; opacity: 0.8;">${item.batas || ''}</span>
                    <span style="font-size: 0.8rem; font-weight: normal; opacity: 0.8;">(${item.guru})</span>
                   </div>
                </li>`;
                } else if (item.mapel.toLowerCase().includes('upacara')) {
                    listHTML += `
                <li class="subject-item upacara">
                  <div class="subject-time" style="background:#BBDEFB; border-color:#1565C0;">Ke-${item.jam}</div>
                  <div class="subject-info">
                    <span class="subject-name">${item.mapel}</span>
                    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap;">
                        <span class="subject-teacher">${item.guru || '-'}</span>
                        <span class="subject-limit"><i class="fa-regular fa-clock"></i> ${item.batas || '-'}</span>
                    </div>
                  </div>
                </li>`;
                } else {
                    listHTML += `
                <li class="subject-item">
                  <div class="subject-time">Ke-${item.jam}</div>
                  <div class="subject-info">
                    <span class="subject-name">${item.mapel}</span>
                    <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap;">
                        <span class="subject-teacher">${item.guru || '-'}</span>
                        <span class="subject-limit"><i class="fa-regular fa-clock"></i> ${item.batas || '-'}</span>
                    </div>
                  </div>
                </li>`;
                }
            });

            dayCard.innerHTML = `
            <div class="day-header">${day.toUpperCase()}</div>
            <ul class="subject-list">
              ${listHTML}
            </ul>
          `;
            container.appendChild(dayCard);
        }
    });

    window.scrollTo(0, 0);
}

// --- NAVIGATION FUNCTIONS ---
function switchKelas(val) {
    if (val) {
        window.location.href = `?kelas=${val}`;
    }
}

function goHome() {
    window.location.href = window.location.pathname;
}

function renderMobileNav(days) {
    mobileNav.innerHTML = '';
    days.forEach(day => {
        const btn = document.createElement('button');
        btn.className = 'mobile-nav-btn';
        btn.innerHTML = `<i class="fa-regular fa-calendar"></i> ${day.substring(0, 3)}`;
        btn.onclick = () => {
            const target = document.getElementById(`section-${day.toLowerCase()}`);
            if (target) {
                const headerOffset = 80;
                const elementPosition = target.getBoundingClientRect().top;
                const offsetPosition = elementPosition + window.pageYOffset - headerOffset;
                window.scrollTo({ top: offsetPosition, behavior: 'smooth' });

                document.querySelectorAll('.mobile-nav-btn').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
            }
        };
        mobileNav.appendChild(btn);
    });
    mobileNav.classList.remove('hidden');
}
